import type {
  StyledOutputComponentGroup,
  StyledOutputPropExtend,
} from "../../styled-output-model/index.js";

import { projectVueStyledComponent } from "./styled/projection.js";
import type { VueModuleImport, VueStyledComponentProjection } from "./styled/types.js";

const generatedBlockHeader =
  "/**\n * Generated by scripts/portable-runtime/generate-cli-registry.ts.\n * Do not edit by hand; update the contract/template instead.\n */";
const vendoredBlockHeader =
  "/**\n * Vendored by the Starwind CLI.\n * You own this file in your project.\n */";
const generatedHtmlHeader =
  "<!-- Generated by scripts/portable-runtime/generate-cli-registry.ts. Do not edit by hand. -->";
const vendoredHtmlHeader =
  "<!-- Vendored by the Starwind CLI. You own this file in your project. -->";
const generatedLineHeaders = [
  "// Generated by scripts/portable-runtime/generate-cli-registry.ts. Do not edit by hand.",
  "// Generated by scripts/portable-runtime/generate-cli-registry.ts. Do not edit by hand; update the contract/template instead.",
] as const;
const vendoredLineHeader =
  "// Vendored by the Starwind CLI.\n// You own this file in your project.";
export const vuePrimitiveQuarantineMarkers = [
  "<!-- Internal non-shipping Vue adapter output. Do not publish, expose through the CLI registry, claim in public docs, or copy into public demo dependencies. -->",
  "// Internal non-shipping Vue adapter output. Do not publish, expose through the CLI registry, claim in public docs, or copy into public demo dependencies.",
] as const;

export const vuePrimitiveEditableContentMarkers = [
  { extensions: [".vue"], markers: [vendoredHtmlHeader], position: "prefix" },
  {
    extensions: [".ts", ".js"],
    markers: [vendoredBlockHeader, vendoredLineHeader],
    position: "prefix",
  },
] as const;

export function projectVuePrimitiveVendoringContent(content: string): string {
  let projected = content
    .replaceAll(generatedBlockHeader, vendoredBlockHeader)
    .replaceAll(generatedHtmlHeader, vendoredHtmlHeader);
  for (const header of generatedLineHeaders) {
    projected = projected.replaceAll(header, vendoredLineHeader);
  }
  for (const marker of vuePrimitiveQuarantineMarkers) {
    projected = projected.replaceAll(`${marker}\n`, "").replaceAll(marker, "");
  }
  return projected;
}

export function collectVueStyledPackageImportSources(args: {
  group: StyledOutputComponentGroup;
  primitiveImportBase: string;
}): string[] {
  const sources = new Set<string>(["vue"]);

  for (const component of args.group.components) {
    const projection = projectVueStyledComponent(args.group, component, {
      directory: "",
      outputRoot: "",
      primitiveImportBase: args.primitiveImportBase,
      primitiveOutputRoot: "",
    });

    for (const entry of projection.imports.entries) {
      const source = getVueModuleImportSource(entry);
      if (source && isPackageImportSource(source)) sources.add(source);
    }

    for (const source of collectProjectedImportSources(projection)) {
      if (isPackageImportSource(source)) sources.add(source);
    }
  }

  return [...sources].sort();
}

function getVueModuleImportSource(entry: VueModuleImport): string | undefined {
  return entry.kind === "framework" ? "vue" : entry.source;
}

function isPackageImportSource(source: string): boolean {
  return !source.startsWith(".") && !source.startsWith("/");
}

function collectProjectedImportSources(projection: VueStyledComponentProjection): string[] {
  const sources = new Set<string>();

  for (const propExtend of projection.props.public.extends) {
    collectPropExtendImportSources(propExtend).forEach((source) => sources.add(source));
  }

  const projectedTypeSources = [
    ...projection.props.public.fields.map((field) => field.type),
    ...projection.props.declared.fields.map((field) => field.type),
    ...projection.models.map((model) => model.type),
    ...projection.emits.flatMap((emit) => emit.parameters.map((parameter) => parameter.type)),
    ...projection.slots.map((slot) => slot.signature),
    ...projection.setup,
  ];
  for (const source of projectedTypeSources) {
    collectImportSources(source).forEach((importSource) => sources.add(importSource));
  }

  return [...sources].sort();
}

function collectPropExtendImportSources(propExtend: StyledOutputPropExtend): string[] {
  return propExtend.kind === "raw" ? collectImportSources(propExtend.code) : [];
}

function collectImportSources(source: string): string[] {
  const importSources = new Set<string>();
  const staticImportPattern =
    /(?:import|export)\s+(?:type\s+)?(?:[^"';]*?\s+from\s+)?["']([^"']+)["']/g;
  const dynamicImportPattern = /import\(["']([^"']+)["']\)/g;

  for (const match of source.matchAll(staticImportPattern)) importSources.add(match[1]!);
  for (const match of source.matchAll(dynamicImportPattern)) importSources.add(match[1]!);

  return [...importSources].sort();
}
